// Mirrors docs/API.md. Your real FastAPI backend must return these shapes.

export interface Health {
  status: 'ok' | string
  version: string
  mode: Record<string, string>
}

export interface TextSymbol {
  id: number
  x: number
  y: number
  w: number
  h: number
  text: string
  role: string
  /** true = copied from the current GUI (prompt G.1); false = generated by the LLM (G.3) */
  unchanged: boolean
}

export interface PredictResponse {
  id: string
  action: string
  images: {
    current: string
    str_current: string
    str_next: string
    str_next_ids: string
    predicted: string
  }
  symbols: TextSymbol[]
  static_text: { x: number; y: number; w: number; h: number; text: string }[]
  timings: Record<string, number>
}

export interface Candidate {
  action: string
  predicted_image: string
  judgement: 'valid' | 'invalid'
  confidence: number
  score: number
  reason: string
}

export interface AgentResponse {
  goal: string
  candidates: Candidate[]
  top2: number[]
  selected_index: number
  selection_reason: string
  timings: Record<string, number>
}

export interface EvaluateResponse {
  s_gc: number
  s_ia: number
  s_ar: number
  s_h: number
  details: { ia_thoughts: string; ar_thoughts: string }
}
